//! Loads `assets/fixtures.json`, generated by
//! `scripts/generate_fixtures.py` from flygym + a real mocap recording.

use serde::Deserialize;

#[derive(Deserialize)]
pub struct Fixtures {
    pub leg_joint_names: Vec<String>,
    pub synthetic_frames: Vec<SyntheticFrame>,
    pub real_frames: Vec<RealFrame>,
    pub native_rate_frames: Vec<NativeRateFrame>,
}

/// A keypoint target exactly reachable by this model's own forward
/// kinematics, generated from a real recorded frame's ground-truth joint
/// angles. Used to check that the solver actually recovers known angles.
#[derive(Deserialize)]
pub struct SyntheticFrame {
    #[allow(dead_code)]
    pub frame: usize,
    pub target_ego: Vec<[f32; 3]>,
    /// 6 legs x 7 DOFs, in the same flattened order as `State::dof_angles`.
    pub ground_truth_dof_angles_per_leg: Vec<Vec<f32>>,
}

impl SyntheticFrame {
    /// Ground-truth DOF angles flattened to match `State::dof_angles`' layout.
    pub fn ground_truth_dof_angles_flat(&self) -> Vec<f32> {
        self.ground_truth_dof_angles_per_leg
            .iter()
            .flatten()
            .copied()
            .collect()
    }
}

/// A real (noisy) mocap frame, rigidly aligned into this model's own frame
/// convention, plus -- for bodies with a reference solver to cross-check
/// against (currently only NeuroMechFly/flygym.ik) -- that solver's own
/// reconstruction for the same target. Sparsely sampled (every 30th recorded
/// frame, ~91ms apart): good for a diverse correctness check, but understates
/// how warm "warm start" is in real continuous use -- see [`NativeRateFrame`]
/// for a warm-start *performance* benchmark instead.
#[derive(Deserialize)]
pub struct RealFrame {
    #[allow(dead_code)]
    pub frame: usize,
    pub target_ego: Vec<[f32; 3]>,
    pub flygym_ik_reconstructed_ego: Option<Vec<[f32; 3]>>,
    #[allow(dead_code)]
    pub flygym_ik_success: Option<bool>,
    #[allow(dead_code)]
    pub flygym_ik_cost: Option<f32>,
}

/// One frame of a *contiguous* run of consecutive recorded frames (no gaps),
/// for benchmarking `solve_frame`'s warm start under the frame-to-frame
/// motion an actual continuous tracking pipeline would see. Performance-only
/// (no flygym.ik reconstruction -- this isn't a correctness fixture).
#[derive(Deserialize)]
pub struct NativeRateFrame {
    #[allow(dead_code)]
    pub frame: usize,
    pub target_ego: Vec<[f32; 3]>,
}

pub fn load(path: impl AsRef<std::path::Path>) -> Fixtures {
    let path = path.as_ref();
    let json_str = std::fs::read_to_string(path)
        .unwrap_or_else(|e| panic!("failed to read fixtures file '{}': {e}", path.display()));
    serde_json::from_str(&json_str)
        .unwrap_or_else(|e| panic!("failed to parse fixtures file '{}': {e}", path.display()))
}
